UPDATE utb_doc_dispatch
SET category = #{category}
  , doc_type = #{docType}
  , dispatch_date = #{dispatchDate}
  , client = #{client}
  , manager = #{manager}
  , doc_content = #{docContent}
  , method = #{method}
  , send_date = #{sendDate}
  , reg_no = #{regNo}
  , ack_yn = #{ackYn}
  , post_addr = #{postAddr}
  , note = #{note}
  , update_user = #{updateUser}
  , update_at = CURRENT_TIMESTAMP
WHERE dispatch_seq = #{dispatchSeq}
  AND office_seq = #{officeSeq}

UPDATE utb_doc_dispatch
SET del_yn = 'Y'
  , update_user = #{userSeq}
  , update_at = CURRENT_TIMESTAMP
WHERE dispatch_seq = #{dispatchSeq}
